import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); c=[]
                while q:
                    y,x=q.pop(); c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append(c)
    return out

def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    o=[r[:] for r in g]
    cs=comps(g,bg); ref=max(cs,key=len)
    refset={(y,x) for y,x in ref}
    markers=[(y,x) for y in range(H) for x in range(W) if g[y][x]!=bg and (y,x) not in refset]
    ys=[y for y,_ in ref]; xs=[x for _,x in ref]
    cy=(min(ys)+max(ys))//2; cx=(min(xs)+max(xs))//2
    for (my,mx) in markers:
        for (y,x) in ref:
            ny,nx=y+(my-cy),x+(mx-cx)
            if 0<=ny<H and 0<=nx<W: o[ny][nx]=g[y][x]
    return o

